	def _load(rel, alpha=False):
		try:
			img = pygame.image.load(rel)
			return img.convert_alpha() if alpha else img.convert()
		except Exception:
			surf = pygame.Surface((72, 72), pygame.SRCALPHA if alpha else 0)
			surf.fill((40, 40, 40, 0) if alpha else (40, 40, 40))
			return surf
	def _run_warning_sequence():
		_FADE_IN_MS   = 800    # configurable: ms to fade in
		_HOLD_MS      = 3000   # configurable: ms to hold at full opacity
		_FADE_OUT_MS  = 600    # configurable: ms to fade out
		_GAP_MS       = 120    # configurable: ms of black between screens
		_BG           = (0, 0, 0)
		_FG           = (220, 215, 205)
		_TITLE_COL    = (255, 255, 255)
		_DIM_COL      = (160, 155, 148)
		_sw, _sh      = screen.get_size()
		_cx           = _sw // 2

		_wf_title  = pygame.font.SysFont("Times New Roman", max(28, int(_sh * 0.048)))
		_wf_body   = pygame.font.SysFont("Times New Roman", max(18, int(_sh * 0.030)))
		_wf_footer = pygame.font.SysFont("Times New Roman", max(13, int(_sh * 0.020)))

		_WARNINGS = [
			(
				"Warning",
				[
					"This game contains flashing lights, visual effects,",
					"and rapidly changing imagery that may affect players",
					"with photosensitive epilepsy or similar conditions.",
					"",
					"Player discretion is advised.",
				],
				"EPILEPSY WARNING",
			),
			(
				"Warning",
				[
					"This game contains violence, death, psychological themes,",
					"moral conflict, and other mature subject matter.",
					"",
					"Player discretion is advised.",
				],
				"SENSITIVE CONTENT WARNING",
			),
			(
				"Warning",
				[
					"Your choices, dialogue, and actions shape the world around you.",
					"",
					"Every decision may affect relationships,",
					"progression, and endings.",
				],
				"IMMERSIVE EXPERIENCE",
			),
		]

		def _render_warning_frame(title_text, body_lines, label_text, alpha):
			surf = pygame.Surface((_sw, _sh))
			surf.fill(_BG)
			# Label (top-center, dimmed)
			_lbl = _wf_footer.render(label_text, True, _DIM_COL)
			surf.blit(_lbl, (_cx - _lbl.get_width() // 2, int(_sh * 0.12)))
			# Divider line
			pygame.draw.line(surf, (70, 65, 60),
				(_cx - 180, int(_sh * 0.17)),
				(_cx + 180, int(_sh * 0.17)), 1)
			# Title
			_ttl = _wf_title.render(title_text, True, _TITLE_COL)
			surf.blit(_ttl, (_cx - _ttl.get_width() // 2, int(_sh * 0.22)))
			# Body lines
			_line_h = _wf_body.get_linesize() + 4
			_body_start_y = int(_sh * 0.34)
			for i, line in enumerate(body_lines):
				if line == "":
					continue
				_ln = _wf_body.render(line, True, _FG)
				surf.blit(_ln, (_cx - _ln.get_width() // 2, _body_start_y + i * _line_h))
			# Apply fade alpha via overlay
			_overlay = pygame.Surface((_sw, _sh))
			_overlay.fill(_BG)
			_overlay.set_alpha(255 - alpha)
			surf.blit(_overlay, (0, 0))
			screen.blit(surf, (0, 0))
			pygame.display.flip()

		def _pump_events_check_quit():
			for _e in pygame.event.get():
				if _e.type == pygame.QUIT:
					pygame.quit()
					sys.exit(0)

		def _black_gap():
			screen.fill(_BG)
			pygame.display.flip()
			_t0 = pygame.time.get_ticks()
			while pygame.time.get_ticks() - _t0 < _GAP_MS:
				_pump_events_check_quit()
				py_clock.tick(60)

		for (_wtitle, _wbody, _wlabel) in _WARNINGS:
			# FADE IN
			_t0 = pygame.time.get_ticks()
			while True:
				_elapsed = pygame.time.get_ticks() - _t0
				if _elapsed >= _FADE_IN_MS:
					break
				_a = int(255 * _elapsed / _FADE_IN_MS)
				_render_warning_frame(_wtitle, _wbody, _wlabel, _a)
				_pump_events_check_quit()
				py_clock.tick(60)
			# HOLD
			_render_warning_frame(_wtitle, _wbody, _wlabel, 255)
			pygame.display.flip()
			_t0 = pygame.time.get_ticks()
			while pygame.time.get_ticks() - _t0 < _HOLD_MS:
				_pump_events_check_quit()
				py_clock.tick(60)
			# FADE OUT
			_t0 = pygame.time.get_ticks()
			while True:
				_elapsed = pygame.time.get_ticks() - _t0
				if _elapsed >= _FADE_OUT_MS:
					break
				_a = int(255 * (1.0 - _elapsed / _FADE_OUT_MS))
				_render_warning_frame(_wtitle, _wbody, _wlabel, _a)
				_pump_events_check_quit()
				py_clock.tick(60)
			_black_gap()

	_run_warning_sequence()
