		pygame.draw.rect(screen, _bar_brd, (_bar_x - 1, _bar_y - 1, _bar_w + 2, _bar_h + 2), 1)
		_fw = max(4, int(_bar_w * _load_progress))
		pygame.draw.rect(screen, _bar_fg, (_bar_x, _bar_y, _fw, _bar_h))
		pygame.draw.rect(screen, _bar_shi, (_bar_x, _bar_y, _fw, max(2, _bar_h // 4)))
		_p = _lf_pct.render(f"{int(_load_progress * 100)}%", True, (160, 155, 145))
		screen.blit(_p, _p.get_rect(midleft=(_bar_x + _bar_w + 10, _bar_y + _bar_h // 2)))
		_t1 = _lf_footer.render(_footer_line1, True, (115, 112, 106))
