	def resolve_collision(entity_x, entity_y, entity_size, dx, dy, walls):
		"""
		Axis-separated collision resolution.
		Returns (resolved_x, resolved_y) after applying dx, dy against walls.
		Safe for any rectangular entity.
		"""
		new_x = entity_x + dx
		test = pygame.Rect(int(new_x), int(entity_y), entity_size, entity_size)
		for w in walls:
			if test.colliderect(w):
				if dx > 0:
					new_x = float(w.left - entity_size)
				elif dx < 0:
					new_x = float(w.right)
				test.x = int(new_x)

		new_y = entity_y + dy
		test = pygame.Rect(int(new_x), int(new_y), entity_size, entity_size)
		for w in walls:
			if test.colliderect(w):
				if dy > 0:
					new_y = float(w.top - entity_size)
				elif dy < 0:
					new_y = float(w.bottom)
				test.y = int(new_y)

		return new_x, new_y

	def _draw_interact_hint(npc, world_x, world_y, label="Talk"):
		"""
		Draws a small [E] prompt above an NPC when the player is nearby.
		Call this every frame when the player's interact_box overlaps the NPC rect.
		"""
		_hint_x = (npc.x - world_x) + 18
		_hint_y = (npc.y - world_y) - 22
		_hint_surf = pygame.Surface((90, 20), pygame.SRCALPHA)
		_hint_surf.fill((10, 10, 20, 180))
		screen.blit(_hint_surf, (_hint_x - 4, _hint_y - 2))
		_hint_text = fonts[15].render(f"[E] {label}", True, (220, 200, 120))
		screen.blit(_hint_text, (_hint_x, _hint_y))

	def _draw_fallback_dialogue(npc_label, lines):
		"""Universal fallback: draws a transparent textbox over the current map."""
		_dlg_box = pygame.Rect(0, screen_y - 180, screen_x, 180)
		_dlg_surf = pygame.Surface((_dlg_box.w, _dlg_box.h), pygame.SRCALPHA)
		_dlg_surf.fill((10, 10, 20, 210))
		screen.blit(_dlg_surf, (_dlg_box.x, _dlg_box.y))
		pygame.draw.rect(screen, (160, 100, 40), _dlg_box, 2)
		screen.blit(fonts[20].render(npc_label, True, (220, 170, 80)), (20, screen_y - 175))
		for _li, _ln in enumerate(lines[:3]):
			screen.blit(fonts[20].render(_ln, True, (230, 230, 220)), (20, screen_y - 148 + _li * 28))
		screen.blit(fonts[15].render("[ Click to continue ]", True, (150, 150, 150)),
					(screen_x - 220, screen_y - 25))

