	def _safe_companion_spawn(companion, player, walls):
		if companion is None:
			return
		_offsets = [
			(80, 0), (-80, 0), (0, 80), (0, -80),
			(120, 0), (-120, 0), (0, 120), (0, -120),
			(80, 80), (-80, 80), (80, -80), (-80, -80),
			(160, 0), (-160, 0), (0, 160), (0, -160),
		]
		for _ox, _oy in _offsets:
			_cx = player.x + _ox
			_cy = player.y + _oy
			_cw = getattr(companion, "size", getattr(companion, "width", 48))
			_ch = getattr(companion, "size", getattr(companion, "height", 48))
			_test_rect = pygame.Rect(_cx, _cy, _cw, _ch)
			_blocked = any(_test_rect.colliderect(_w) for _w in walls)
			if not _blocked:
				companion.x = _cx
				companion.y = _cy
				return
		companion.x = player.x
		companion.y = player.y

		if companion_npc is None:
			return
		_offsets = [(offset, 0), (-offset, 0), (0, offset), (0, -offset),
					(offset, offset), (-offset, -offset)]
		for _dx, _dy in _offsets:
			_tx = player.x + _dx
			_ty = player.y + _dy
			_tr = pygame.Rect(int(_tx), int(_ty), 72, 72)
			_hit = any(_tr.colliderect(_w) for _w in walls)
			if not _hit:
				companion_npc.x = _tx
				companion_npc.y = _ty
				companion_npc.rect.topleft = (int(_tx), int(_ty))
				return
		companion_npc.x = player.x + 50
		companion_npc.y = player.y
		companion_npc.rect.topleft = (int(companion_npc.x), int(companion_npc.y))

	def _make_hostile(npc):
		npc.state = "hostile"
		if "hostile" not in npc.allowed_states:
			npc.allowed_states = ["hostile"]

	def _reset_hostile_npc_positions(npcs_list, player_ref, min_dist=350):
		for _npc in npcs_list:
			if _npc.state == "hostile":
				dx = _npc.x - player_ref.x
				dy = _npc.y - player_ref.y
				dist = (dx ** 2 + dy ** 2) ** 0.5
				if dist < min_dist:
					import math as _rm
					angle = _rm.atan2(dy, dx) if dist > 0 else _rm.random() * 6.28
					_npc.x = player_ref.x + _rm.cos(angle) * min_dist
					_npc.y = player_ref.y + _rm.sin(angle) * min_dist
					_npc.rect.topleft = (int(_npc.x), int(_npc.y))

	_env_particles = {}

	def _emit_particles(map_key, ptype):
		"""Draw lightweight ambient particles for a map.
		ptype: 'embers'|'fog'|'rain'|'smoke'|'holy'|'sea'
		"""
		import math as _m
		if map_key not in _env_particles:
			_count = 15
			if ptype == "rain":
				_env_particles[map_key] = [
					[random.randint(0, screen_x), random.uniform(0, screen_y),
					 random.uniform(4, 8)] for _ in range(_count)]
			else:
				_env_particles[map_key] = [
					[random.randint(0, screen_x), random.uniform(0, screen_y),
					 random.uniform(0.3, 1.2), random.uniform(0, 6.28)] for _ in range(_count)]
		pts = _env_particles[map_key]
		_t = pygame.time.get_ticks()
		for _pt in pts:
			if ptype == "embers":
				_pt[0] += _m.sin(_pt[3] + _t / 800) * 0.5
				_pt[1] -= _pt[2] * 0.4
				if _pt[1] < -5: _pt[1] = screen_y
				_ps = pygame.Surface((3, 3), pygame.SRCALPHA)
				_ps.fill((255, 120, 30, 140))
				screen.blit(_ps, (int(_pt[0]), int(_pt[1])))
			elif ptype == "fog":
				_pt[0] += 0.2
				if _pt[0] > screen_x + 40: _pt[0] = -40.0
				_ps = pygame.Surface((80, 30), pygame.SRCALPHA)
				_ps.fill((200, 200, 200, 18))
				screen.blit(_ps, (int(_pt[0]), int(_pt[1])))
			elif ptype == "rain":
				_pt[1] += _pt[2]
				if _pt[1] > screen_y: _pt[1] = 0.0
				pygame.draw.line(screen, (150, 180, 220, 120),
								 (int(_pt[0]), int(_pt[1])),
								 (int(_pt[0]) - 1, int(_pt[1]) + 8), 1)
			elif ptype == "holy":
				_pt[1] -= _pt[2] * 0.3
				_pt[3] += 0.03
				if _pt[1] < -5: _pt[1] = float(screen_y)
				_ps = pygame.Surface((4, 4), pygame.SRCALPHA)
				_ps.fill((255, 255, 200, 100))
				screen.blit(_ps, (int(_pt[0] + _m.sin(_pt[3]) * 10), int(_pt[1])))
			elif ptype == "sea":
				_pt[0] += _m.sin(_pt[3] + _t / 600) * 0.8
				_pt[1] += _m.cos(_pt[3] + _t / 600) * 0.4
				if _pt[0] < 0 or _pt[0] > screen_x: _pt[0] = random.randint(0, screen_x)
				if _pt[1] < 0 or _pt[1] > screen_y: _pt[1] = random.randint(0, screen_y)
				_ps = pygame.Surface((5, 2), pygame.SRCALPHA)
				_ps.fill((160, 200, 255, 80))
				screen.blit(_ps, (int(_pt[0]), int(_pt[1])))
			elif ptype == "smoke":
				_pt[1] -= _pt[2] * 0.2
				_pt[0] += _m.sin(_pt[3] + _t / 1000) * 0.3
				if _pt[1] < -10: _pt[1] = float(screen_y)
				_ps = pygame.Surface((12, 12), pygame.SRCALPHA)
				_ps.fill((60, 60, 60, 30))
				screen.blit(_ps, (int(_pt[0]), int(_pt[1])))

	_dlg_sfx_last_state = [None]

	def _dlg_sfx(voice_type, dlg_state_key=None):
		"""Play dialogue SFX only once per unique dialogue state.
		Pass the state string as dlg_state_key to prevent per-frame doubling.
		If no key is given, falls back to old always-play behaviour (legacy)."""
		if dlg_state_key is not None and _dlg_sfx_last_state[0] == dlg_state_key:
			return
		_dlg_sfx_last_state[0] = dlg_state_key
		_voice_map = {
			"male": "music/Masculune voice (Nahtt).wav",
			"female": "music/Feminine voice (Nahtt).wav",
		}
		_f = _voice_map.get(voice_type)
		if _f:
			_sfx(_f, 0.5)

	def _dlg_advance(events, next_state, flag_setter=None, reset_npcs=True):
		"""Unified dialogue input handler.
		Returns next_state if any valid input (click, Space, Return, E) is pressed.
		Returns pre_state if Escape is pressed.
		Returns None if no input this frame.
		Calls flag_setter() before transitioning if provided."""
		for _ev in events:
			if _ev.type == pygame.MOUSEBUTTONDOWN and _ev.button == 1:
				if flag_setter: flag_setter()
				return next_state
			if _ev.type == pygame.KEYDOWN:
				if _ev.key in (pygame.K_SPACE, pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_e):
					if flag_setter: flag_setter()
					return next_state
				if _ev.key == pygame.K_ESCAPE:
					if reset_npcs:
						_reset_hostile_npc_positions(npcs, p)
					return pre_state
		return None

	class Player:
		def __init__(self, class_name, x, y, pw, ph):
			self.class_name = class_name
			self.x = float(x)
			self.y = float(y)
			self.pw = pw
			self.ph = ph
			self.size = 40
			self.dx = 0
			self.dy = 0
			self.speed = PLAYER_CLASSES.get(class_name, user_add_speed)
			self.facing = "down"
			self.state = "idle"
			self.is_attacking = False
			self.sprite_type = PLAYER_SPRITES.get(class_name, "no")
			self.anim_frame = 0
			self.anim_timer = 0
			self._step_timer = 0

		def update_input(self):

			self.dx = 0
			self.dy = 0
			if keys[controls["move_left"]]:
				self.dx = -self.speed
				self.facing = "left"
			if keys[controls["move_right"]]:
				self.dx = self.speed
				self.facing = "right"
			if keys[controls["move_up"]]:
				self.dy = -self.speed
				self.facing = "up"
			if keys[controls["move_down"]]:
				self.dy = self.speed
				self.facing = "down"
			if self.dx or self.dy:
				self.state = "walk"
				self._step_timer += 1
				if self._step_timer >= 20:
					self._step_timer = 0
					_sfx("sounds/footstep.wav", 0.4)
			else:
				self.state = "idle"
			if self.dx != 0 and self.dy != 0:
				self.dx *= 0.7071
				self.dy *= 0.7071

		def move(self, walls):
			self.x, self.y = resolve_collision(
				self.x, self.y, self.size, self.dx, self.dy, walls
			)

		def border(self):

			if self.x < 0:
				self.x = 0.0
			if self.x > self.pw - self.size:
				self.x = float(self.pw - self.size)
			if self.y < 0:
				self.y = 0.0
			if self.y > self.ph - self.size:
				self.y = float(self.ph - self.size)

		def attack(self):
			self.is_attacking = True
			self.state = "attack"
			_sfx("sounds/attack.wav", 0.8)

		def get_rect(self):
			return pygame.Rect(int(self.x), int(self.y), self.size, self.size)

		def interact_rect(self):
			size = 40
			if self.facing == "up":
				return pygame.Rect(self.x, self.y - size, size, size)
			elif self.facing == "down":
				return pygame.Rect(self.x, self.y + self.size, size, size)
			elif self.facing == "left":
				return pygame.Rect(self.x - size, self.y, size, size)
			elif self.facing == "right":
				return pygame.Rect(self.x + self.size, self.y, size, size)

		def draw(self, screen, world_x, world_y):
			sprite_set = SPRITES[self.sprite_type]
			if self.state == "idle":
				sprite = sprite_set["idle"][self.facing]
			elif self.state == "walk":
				frames = sprite_set["walk"][self.facing]
				self.anim_timer += delta
				if self.anim_timer > 0.15:
					self.anim_timer = 0
					self.anim_frame = (self.anim_frame + 1) % len(frames)
				sprite = frames[self.anim_frame]
			elif self.state == "attack":
				frames = sprite_set["attack"][self.facing]
				self.anim_timer += 1
				if self.anim_timer > 8:
					self.anim_timer = 0
					self.anim_frame = (self.anim_frame + 1) % len(frames)
				sprite = frames[self.anim_frame]
			else:
				sprite = sprite_set["idle"][self.facing]
			draw_x = int(self.x - world_x) - 16
			draw_y = int(self.y - world_y) - 16

			_HORROR_TYPES = {
				"corrupted1_cultist", "corrupted2_cultist", "corrupted3_cultist",
				"amalgamated_villagers", "amalgamated_knights", "amalgamated_civillians",
				"melted_male_villager", "melted_female_villager",
				"caligo_manifestation", "imprisoned_experiment_hostile",
			}
			_npc_visual_key = getattr(self, "sprite_type", getattr(self, "sprite_key", ""))
			if _npc_visual_key in _HORROR_TYPES and self.state in ("hostile", "caligo"):
				import math as _hm
				_t = pygame.time.get_ticks()

				_pulse = int(120 + 80 * _hm.sin(_t / 250.0))
				_circle_surf = pygame.Surface((88, 20), pygame.SRCALPHA)
				pygame.draw.ellipse(_circle_surf, (200, 0, 0, _pulse), (0, 0, 88, 20))
				screen.blit(_circle_surf, (draw_x - 8, draw_y + 60))

				screen.blit(sprite, (draw_x, draw_y))
			else:
				screen.blit(sprite, (draw_x, draw_y))

	class NPC:
		def __init__(self, allowed_states, state, x, y, pw, ph, sprite_key):
			self.allowed_states = allowed_states
			self.state = state
			self.x = x
			self.y = y
			self.pw = pw
			self.ph = ph
			self.sprite_key = sprite_key
			self.sprites = SPRITES.get(sprite_key, SPRITES["no"])
			self.action = "idle"
			self.frame = 0
			self.anim_timer = 0
			self.anim_speed = 10
			self.direction = random.choice(["up", "down", "left", "right"])
			self.speed = 4
			self.move_timer = random.randint(10, 120)
			self.move_time = 120
			self.stunned = False
			self.stun_timer = 0
			self.stun_time = 60
			self.rect = pygame.Rect(self.x, self.y, 72, 72)
			self.last_pos = (self.x, self.y)
			self.stuck_timer = 0
			self.stuck_time = 10
			self.maneuvering = False
			self.maneuver_timer = 0
			self.maneuver_time = 45
			self.moving = False
			self.follow_distance = 90
			self.teleport_distance = 500
			self.companion_speed = 2
			self._caligo_phase = "stalk"
			self._caligo_phase_timer = 0.0
			self._caligo_burst_cooldown = 0.0
			self._caligo_pause_timer = 0.0
			self._caligo_stalk_speed = 1
			self._caligo_burst_speed = 14

		def get_rect(self):
			return pygame.Rect(self.x, self.y, 72, 72)

		def spawn_safe(self, walls):
			for _ in range(1000):
				x = random.randint(0, self.pw - 72)
				y = random.randint(0, self.ph - 72)
				test_rect = pygame.Rect(x, y, 72, 72)
				collide = False
				for w in walls:
					if test_rect.colliderect(w):
						collide = True
						break
				if not collide:
					self.x = x
					self.y = y
					self.rect.topleft = (x, y)
					return

		def update(self, player, walls, entities):
			self.moving = False
			self._push_out_of_walls(walls)
			if self.stunned:
				self.stun_timer -= 1
				if self.stun_timer <= 0:
					self.stunned = False
				return
			if (self.x, self.y) == self.last_pos:
				self.stuck_timer += 1
			else:
				self.stuck_timer = 0
				self.last_pos = (self.x, self.y)
			if self.sprite_key == "caligo_manifestation":
				if self.state != "hostile":
					self.state = "hostile"
					if "hostile" not in self.allowed_states:
						self.allowed_states = ["hostile"]
				self.caligo_horror_update(player, walls, entities)

				self.animate()
			elif self.state == "evade":
				if "evade" in self.allowed_states:
					self._evade_from_player(player, walls, entities)
				if self.rect.colliderect(player.get_rect()):
					self.interact(player)
				return
			if self.state == "hostile":
				if "hostile" not in self.allowed_states:
					return
				if self.stuck_timer >= self.stuck_time:
					self.maneuvering = True
					self.maneuver_timer = self.maneuver_time
					self.direction = random.choice(["up", "down", "left", "right"])
					self.stuck_timer = 0
				if self.maneuvering:
					self.maneuver_timer -= 1
					self.move_direction(walls, entities, player)
					if self.maneuver_timer <= 0:
						self.maneuvering = False
				else:
					self.follow_player(player, walls, entities)

				_sep_radius = 72
				for _other in entities:
					if _other is self:
						continue
					_ox = _other.x - self.x
					_oy = _other.y - self.y
					_dist = (_ox ** 2 + _oy ** 2) ** 0.5
					if 0 < _dist < _sep_radius:
						_push = (_sep_radius - _dist) / _sep_radius * 2.0
						self.x -= (_ox / _dist) * _push
						self.y -= (_oy / _dist) * _push
						self.rect.topleft = (int(self.x), int(self.y))
				if self.rect.colliderect(player.get_rect()):
					self.interact(player)

			elif self.state == "roaming":
				if "roaming" in self.allowed_states:
					self.move_timer -= 1
					if self.move_timer <= 0:
						self.direction = random.choice(["up", "down", "left", "right"])
						self.move_timer = random.randint(10, 120)
					self.move_direction(walls, entities, player)
			elif self.state == "companion":
				if "companion" in self.allowed_states:
					self.companion_follow(player, walls, entities)
			self.animate()

		def animate(self):
			if self.moving:
				self.action = "walk"
			else:
				self.action = "idle"
			self.anim_timer += delta
			if self.anim_timer >= 0.12:
				self.anim_timer = 0
				action_set = self.sprites.get(self.action, None)
				if action_set is not None:
					dir_set = action_set.get(self.direction, None)
					if isinstance(dir_set, list) and len(dir_set) > 1:
						self.frame = (self.frame + 1) % len(dir_set)
					else:
						self.frame = (self.frame + 1) % 2
				else:
					self.frame = (self.frame + 1) % 2

		def move_direction(self, walls, entities, player):
			dx = 0
			dy = 0
			if self.direction == "up":
				dy = -self.speed
			elif self.direction == "down":
				dy = self.speed
			elif self.direction == "left":
				dx = -self.speed
			elif self.direction == "right":
				dx = self.speed
			self.try_move(dx, dy, walls, entities, player)

		def follow_player(self, player, walls, entities):
			dx = player.x - self.x
			dy = player.y - self.y
			dist = (dx ** 2 + dy ** 2) ** 0.5
			if dist < 1.0:
				return
			move_x = 0
			move_y = 0
			if abs(dx) >= abs(dy):
				move_x = self.speed if dx > 0 else -self.speed
				self.direction = "right" if dx > 0 else "left"
				if abs(dy) > 5:
					move_y = self.speed if dy > 0 else -self.speed
					self.direction = "down" if dy > 0 else "up"
			else:
				move_y = self.speed if dy > 0 else -self.speed
				self.direction = "down" if dy > 0 else "up"
				if abs(dx) > 5:
					move_x = self.speed if dx > 0 else -self.speed
					self.direction = "right" if dx > 0 else "left"
			self.try_move(move_x, move_y, walls, entities, player)

		def _push_out_of_walls(self, walls):
			current = pygame.Rect(int(self.x), int(self.y), 72, 72)
			# Fast path: no overlap
			if not any(current.colliderect(w) for w in walls):
				return
			# Spiral search in 4-pixel increments up to 400 px radius
			step = 4
			for radius in range(step, 400, step):
				for ox in range(-radius, radius + 1, step):
					for oy in range(-radius, radius + 1, step):
						if abs(ox) != radius and abs(oy) != radius:
							continue
						candidate = pygame.Rect(int(self.x) + ox, int(self.y) + oy, 72, 72)
						if not any(candidate.colliderect(w) for w in walls):
							self.x = float(candidate.x)
							self.y = float(candidate.y)
							self.rect.topleft = (int(self.x), int(self.y))
							# Reset stuck-timer so pathfinding resumes normally
							self.stuck_timer = 0
							self.maneuvering = False
							return

		def try_move(self, dx, dy, walls, entities, player):

			moved = False

			if dx != 0:
				new_x = self.x + dx
				test_rect = pygame.Rect(int(new_x), int(self.y), 72, 72)
				x_blocked = False
				for w in walls:
					if test_rect.colliderect(w):
						x_blocked = True
						break
				if not x_blocked and self.state != "hostile":
					for e in entities:
						if e is not self and test_rect.colliderect(e.get_rect()):
							x_blocked = True
							break
					if not x_blocked and test_rect.colliderect(player.get_rect()):
						x_blocked = True
				if not x_blocked:
					self.x = new_x
					moved = True

			if dy != 0:
				new_y = self.y + dy
				test_rect = pygame.Rect(int(self.x), int(new_y), 72, 72)
				y_blocked = False
				for w in walls:
					if test_rect.colliderect(w):
						y_blocked = True
						break
				if not y_blocked and self.state != "hostile":
					for e in entities:
						if e is not self and test_rect.colliderect(e.get_rect()):
							y_blocked = True
							break
					if not y_blocked and test_rect.colliderect(player.get_rect()):
						y_blocked = True
				if not y_blocked:
					self.y = new_y
					moved = True

			self.rect.topleft = (int(self.x), int(self.y))
			self.moving = moved

		def caligo_horror_update(self, player, walls, entities):
			import math as _math
			self._caligo_phase_timer += 1
			dx = player.x - self.x
			dy = player.y - self.y
			dist = (dx ** 2 + dy ** 2) ** 0.5
			if self._caligo_phase == "stalk":
				self.speed = self._caligo_stalk_speed
				if self._caligo_phase_timer > random.randint(90, 210):
					self._caligo_phase = "burst" if random.random() < 0.65 else "pause"
					self._caligo_phase_timer = 0
				if dist > 40:
					self.follow_player(player, walls, entities)
			elif self._caligo_phase == "burst":
				self.speed = self._caligo_burst_speed
				if self._caligo_phase_timer > random.randint(18, 45):
					self._caligo_phase = "pause" if random.random() < 0.5 else "stalk"
					self._caligo_phase_timer = 0
				if dist > 40:
					self.follow_player(player, walls, entities)
			elif self._caligo_phase == "pause":
				self.speed = 0
				self.moving = False
				if self._caligo_phase_timer > random.randint(30, 80):
					self._caligo_phase = random.choice(["stalk", "stalk", "burst"])
					self._caligo_phase_timer = 0
			if self.rect.colliderect(player.get_rect()):
				self.interact(player)

		def _evade_from_player(self, player, walls, entities):
			dx = self.x - player.x
			dy = self.y - player.y
			dist = (dx ** 2 + dy ** 2) ** 0.5
			if dist < 900:
				if dist > 0:
					norm_x = dx / dist
					norm_y = dy / dist
				else:
					norm_x, norm_y = 1.0, 0.0
				move_x = norm_x * self.speed
				move_y = norm_y * self.speed
				if abs(dx) >= abs(dy):
					self.direction = "right" if dx > 0 else "left"
				else:
					self.direction = "down" if dy > 0 else "up"
				old_x, old_y = self.x, self.y
				self.try_move(move_x, move_y, walls, entities, player)
				if self.x == old_x and self.y == old_y:
					self.try_move(move_x, 0, walls, entities, player)
				if self.x == old_x and self.y == old_y:
					self.try_move(0, move_y, walls, entities, player)
				if self.x == old_x and self.y == old_y:
					self.try_move(-move_y, move_x, walls, entities, player)
			else:
				self.moving = False

		def companion_follow(self, player, walls, entities):
			dx = player.x - self.x
			dy = player.y - self.y
			dist = (dx ** 2 + dy ** 2) ** 0.5

			if dist > self.teleport_distance:
				self.x = player.x + 50
				self.y = player.y + 50
				self.rect.topleft = (self.x, self.y)
				return

			if dist <= self.follow_distance:
				self.moving = False

				if abs(dx) >= abs(dy):
					self.direction = "right" if dx > 0 else "left"
				else:
					self.direction = "down" if dy > 0 else "up"
				return

			old_speed = self.speed
			self.speed = self.companion_speed

			if abs(dx) >= abs(dy):
				self.direction = "right" if dx > 0 else "left"
				move_x = self.speed if dx > 0 else -self.speed
				self.try_move(move_x, 0, walls, entities, player)
			else:
				self.direction = "down" if dy > 0 else "up"
				move_y = self.speed if dy > 0 else -self.speed
				self.try_move(0, move_y, walls, entities, player)

			self.speed = old_speed

		def interact(self, player):
			self.stunned = True
			self.stun_timer = self.stun_time

		def draw(self, screen, world_x, world_y):
			action_set = self.sprites.get(self.action, None)
			if action_set is None:
				action_set = self.sprites.get("idle", SPRITES["no"]["idle"])
			dir_set = action_set.get(self.direction, None)
			if dir_set is None:
				idle_set = self.sprites.get("idle", SPRITES["no"]["idle"])
				dir_set = idle_set.get(self.direction, idle_set.get("down", SPRITES["no"]["idle"]["down"]))
			if isinstance(dir_set, list):
				if len(dir_set) == 0:
					idle_set = self.sprites.get("idle", SPRITES["no"]["idle"])
					dir_set = idle_set.get(self.direction, idle_set.get("down", SPRITES["no"]["idle"]["down"]))
					if isinstance(dir_set, list) and len(dir_set) > 0:
						sprite = dir_set[0]
					elif not isinstance(dir_set, list):
						sprite = dir_set
					else:
						sprite = SPRITES["no"]["idle"]["down"]
				else:
					_frame_idx = (self.frame // 4) % len(dir_set)
					sprite = dir_set[_frame_idx]
			else:
				sprite = dir_set
			if sprite is None:
				sprite = SPRITES["no"]["idle"]["down"]
			draw_x = self.x - world_x
			draw_y = self.y - world_y

			_HORROR_TYPES = {
				"corrupted1_cultist", "corrupted2_cultist", "corrupted3_cultist",
				"amalgamated_villagers", "amalgamated_knights", "amalgamated_civillians",
				"melted_male_villager", "melted_female_villager",
				"caligo_manifestation", "imprisoned_experiment_hostile",
			}
			_npc_visual_key = getattr(self, "sprite_type", getattr(self, "sprite_key", ""))
			if _npc_visual_key in _HORROR_TYPES and self.state in ("hostile", "caligo"):
				import math as _hm
				_t = pygame.time.get_ticks()

				_pulse_alpha = int(120 + 80 * _hm.sin(_t / 250.0))
				_circle_surf = pygame.Surface((88, 24), pygame.SRCALPHA)
				pygame.draw.ellipse(_circle_surf, (200, 0, 0, _pulse_alpha), (0, 0, 88, 24))
				screen.blit(_circle_surf, (draw_x - 8, draw_y + 60))

				_shake_x = int(1 * _hm.sin(_t / 80.0 + self.x))
				_shake_y = int(1 * _hm.cos(_t / 75.0 + self.y))
				screen.blit(sprite, (draw_x + _shake_x, draw_y + _shake_y))
			else:
				screen.blit(sprite, (draw_x, draw_y))

	def player(class_name, x, y, pw, ph):
		return Player(class_name, x, y, pw, ph)

	def _fade_to_black_and_blit(screen, screen_x, screen_y):
		_fade_surf = pygame.Surface((screen_x, screen_y))
		_fade_surf.fill((0, 0, 0))
		for _alpha in range(0, 256, 12):
			_fade_surf.set_alpha(_alpha)
			screen.blit(_fade_surf, (0, 0))
			pygame.display.flip()
			pygame.time.delay(10)

		_fade_surf.set_alpha(255)
		screen.blit(_fade_surf, (0, 0))
		pygame.display.flip()
		pygame.time.delay(16)

		screen.fill((0, 0, 0))
		for _ev in pygame.event.get():
			pass

