	_hostile_npc_pos_cache = {}

	def _cache_hostile_positions(npc_list):
		for _n in npc_list:
			if _n.state == "hostile":
				_hostile_npc_pos_cache[id(_n)] = (_n.x, _n.y)

	def _all_map_enemies_dead(npc_pool_list):
		"""Return True when every NPC in npc_pool_list has been killed.
		Requires at least one NPC to have been registered as killed,
		preventing a false positive when npcs[] is simply empty (e.g. on
		character select or before the map has been visited)."""
		if not npc_pool_list:
			return False
		# Must have actually killed at least one NPC from this pool
		if not any(id(_npc) in _killed_npc_ids for _npc in npc_pool_list):
			return False
		for _npc in npc_pool_list:
			alive_in_scene = _npc in npcs
			registered_dead = id(_npc) in _killed_npc_ids
			if alive_in_scene and not registered_dead:
				return False
		return True

	def _restore_hostile_positions(npc_list):
		for _n in npc_list:
			_cached = _hostile_npc_pos_cache.get(id(_n))
			if _cached:
				_n.x, _n.y = _cached

	def _make_evade(npc):
		npc.state = "evade"
		if "evade" not in npc.allowed_states:
			npc.allowed_states = ["evade"]

