	def load_npcs_for_map(map_key, character):
		nonlocal shaman_companion_npc_ref
		pool = NPC_POOLS.get(map_key, {})
		new_npcs = list(pool.get(character, []))

		SHAMAN_BANNED_MAPS = {"map_02", "map_03", "map_04", "map_05", "map_06",
							  "map_07", "map_08", "map_09", "map_44"}
		if shaman_companion_active and map_key not in SHAMAN_BANNED_MAPS:
			if shaman_companion_npc_ref is not None and shaman_companion_npc_ref not in new_npcs:
				new_npcs.append(shaman_companion_npc_ref)

		npcs[:] = new_npcs
		entity_walls[:] = []

		player_sprite_key = PLAYER_SPRITES.get(character)
		if player_sprite_key:
			npcs[:] = [npc for npc in npcs
					   if npc.sprite_key != player_sprite_key
					   or npc is map44_npc_lucidus]

		if character == "priest" and map_key == "map_04":
			for npc in npcs:
				npc.state = "roaming"

	npcs = []

