	_TOOLTIP_FONT_CACHE: dict = {}

	def _get_font(size: int) -> pygame.font.Font:
		if size not in _TOOLTIP_FONT_CACHE:
			_TOOLTIP_FONT_CACHE[size] = pygame.font.SysFont("Arial", size)
		return _TOOLTIP_FONT_CACHE[size]

	def _draw_tooltip(screen, mx, my, item_name, uv, craft_index_val):
		data = GAME_ITEMS.get(item_name)
		if data is None:
			return
		itype = data.get("type", "")
		isubtype = data.get("subtype", "")
		desc = data.get("description", "")
		effect = data.get("effect", "")
		pad = 8
		lh = 18
		lines = []
		lines.append(("title", item_name))
		tag = f"{itype}  ·  {isubtype}".upper()
		lines.append(("tag", tag))
		lines.append(("sep", ""))
		if itype in ("armour", "weapon", "accessory"):
			slot = _SLOT_MAP.get(isubtype, "")
			equipped = uv.get(f"user_item_{slot}", "")
			is_equipped = (equipped == item_name)
			if data["defense"] > 0:
				lines.append(("stat", f"DEF  +{data['defense']}"))
			if data["damage"] > 0:
				lines.append(("stat", f"DMG  +{data['damage']}"))
			if data["speed"] != 0:
				lines.append(("stat", f"SPD  {'+' if data['speed'] > 0 else ''}{data['speed']}"))
			if data["mind_res"] != 0:
				lines.append(("stat", f"MIND RES  {'+' if data['mind_res'] > 0 else ''}{data['mind_res']}"))
			lines.append(("sep", ""))
			action = "[ UNEQUIP ]" if is_equipped else "[ EQUIP ]"
			lines.append(("action", action))
		elif itype == "book":
			if effect:
				eff_display = effect.replace("learnskill#", "Teaches: ").replace("gainstatus#", "Inflicts: ").replace(
					"save", "Special: save")
				lines.append(("stat", eff_display))
			lines.append(("sep", ""))
			lines.append(("action", "[ READ / USE ]"))
		elif isubtype == "potion":
			if effect:
				lines.append(("stat", f"Effect: {effect}"))
			lines.append(("sep", ""))
			lines.append(("action", "[ USE ]"))
		elif isubtype == "material":
			recipes = CRAFT_RECIPES.get(item_name, [])
			if recipes:
				lines.append(("label", "Craftable items:"))
				for idx, (result, qty) in enumerate(recipes):
					marker = "▶ " if idx == craft_index_val % len(recipes) else "  "
					lines.append(("craft", f"{marker}{result}  (needs ×{qty})"))
				lines.append(("hint", "↑ ↓  to browse  |  ENTER to craft"))
			else:
				lines.append(("label", "No known recipes."))
		lines.append(("sep", ""))
		words = desc.split()
		row = ""
		for w in words:
			if len(row) + len(w) + 1 > 32:
				lines.append(("desc", row.strip()))
				row = w + " "
			else:
				row += w + " "
		if row.strip():
			lines.append(("desc", row.strip()))
		title_font = _get_font(15)
		body_font = _get_font(13)
		max_w = 0
		for kind, text in lines:
			f = title_font if kind == "title" else body_font
			if text:
				w = f.size(text)[0]
				max_w = max(max_w, w)
		box_w = max_w + pad * 2
		box_h = len(lines) * lh + pad * 2
		scr_w, scr_h = screen.get_size()
		tx = mx + 14
		ty = my + 14
		if tx + box_w > scr_w:
			tx = mx - box_w - 6
		if ty + box_h > scr_h:
			ty = my - box_h - 6
		surf = pygame.Surface((box_w, box_h), pygame.SRCALPHA)
		surf.fill((15, 10, 20, 210))
		pygame.draw.rect(surf, (180, 140, 60), surf.get_rect(), 1)
		screen.blit(surf, (tx, ty))
		COLOR = {
			"title": (255, 220, 100),
			"tag": (140, 140, 160),
			"sep": (0, 0, 0),
			"stat": (200, 230, 200),
			"label": (200, 200, 200),
			"craft": (160, 210, 255),
			"hint": (110, 110, 130),
			"action": (100, 220, 130),
			"desc": (190, 190, 190),
		}
		cy = ty + pad
		for kind, text in lines:
			if kind == "sep" or not text:
				cy += lh // 2
				continue
			f = title_font if kind == "title" else body_font
			col = COLOR.get(kind, (255, 255, 255))
			screen.blit(f.render(text, True, col), (tx + pad, cy))
			cy += lh

	def _adjust_stats(uv, data, equip):
		sign = 1 if equip else -1
		uv["user_def"] = uv.get("user_def", 0) + sign * data.get("defense", 0)
		uv["user_str"] = uv.get("user_str", 0) + sign * data.get("damage", 0)
		uv["user_agi"] = uv.get("user_agi", 0) + sign * data.get("speed", 0)
		uv["user_mind_resistance"] = uv.get("user_mind_resistance", 0) + sign * data.get("mind_res", 0)

	def _apply_equip_toggle(img_key, ukey, uv):
		item_name = _IMAGE_KEY_TO_NAME.get(img_key)
		if not item_name:
			return
		data = GAME_ITEMS.get(item_name)
		if not data:
			return
		itype = data.get("type")
		isubtype = data.get("subtype")
		if itype not in ("armour", "weapon", "accessory"):
			return
		slot = _SLOT_MAP.get(isubtype, "")
		slot_uv = f"user_item_{slot}"
		if not slot:
			return
		if uv.get(slot_uv) == item_name:
			uv[slot_uv] = ""
			_adjust_stats(uv, data, equip=False)
		else:
			prev = uv.get(slot_uv, "")
			if prev and prev in GAME_ITEMS:
				_adjust_stats(uv, GAME_ITEMS[prev], equip=False)
			uv[slot_uv] = item_name
			_adjust_stats(uv, data, equip=True)

	def _apply_item_use(slot_index, ukey, uv):
		match slot_index:
			case 0:
				uv["user_item_book_of_crafsmanship"] -= 1
				uv["user_skill_craftsmanship"] = 1
				_craft_pool = [
					"user_item_red_vial", "user_item_green_herb", "user_item_blue_herb",
					"user_item_betadine", "user_item_antibiotics", "user_item_empty_vial",
					"user_item_stick", "user_item_leather_scraps", "user_item_raw_iron",
					"user_item_wooden_plank", "user_item_paper", "user_item_ale",
					"user_item_rum", "user_item_wine",
				]
				_craft_count = random.randint(1, 3)
				for _ in range(_craft_count):
					_craft_item = random.choice(_craft_pool)
					uv[_craft_item] = uv.get(_craft_item, 0) + 1
			case 1:
				uv["user_item_book_of_agility"] -= 1;
				uv["user_skill_agilityaugmentation"] = 1
			case 2:
				uv["user_item_book_of_healing"] -= 1;
				uv["user_skill_healing"] = 1
			case 3:
				uv["user_item_book_of_instincts"] -= 1;
				uv["user_skill_battleinstinct"] = 1
			case 4:
				uv["user_item_book_of_stars"] -= 1;
				uv["user_skill_foresight"] = 1
			case 5:
				uv["user_item_book_of_the_secrets"] -= 1;
				uv["user_mind_state"] += 1
			case 6:
				uv["user_item_book_of_enlightenment"] -= 1
				uv["user_mind_state"] = int(uv.get("user_mind_state", user_mind_state) * 0.5)
			case 7:
				uv["user_item_book_of_cowardice_i"] -= 1;
				uv["user_skill_escape"] = 1
			case 8:
				uv["user_item_book_of_cowardice_ii"] -= 1;
				uv["user_skill_sprint"] = 1
			case 9:
				uv["user_item_book_of_pestilence_i"] -= 1;
				uv["user_status_bleeding"] = 1
			case 10:
				uv["user_item_book_of_pestilence_ii"] -= 1;
				uv["user_status_infection"] = 1
			case 11:
				uv["user_item_book_of_pestilence_iii"] -= 1;
				uv["user_status_brokenbones"] = 1
			case 12:
				uv["user_item_book_of_pestilence_iv"] -= 1;
				uv["user_status_stun"] = 1
			case 13:
				uv["user_item_book_of_pestilence_v"] -= 1;
				uv["user_status_confusion"] = 1
			case 14:
				uv["user_item_book_of_pestilence_vi"] -= 1;
				uv["user_status_blindness"] = 1
			case 15:
				uv["user_item_book_of_pestilence_vii"] -= 1;
				uv["user_status_critical"] = 1
			case 16:
				uv["user_item_book_of_pestilence_viii"] -= 1;
				uv["user_status_infected"] = 1
			case 17:
				uv["user_item_book_of_trade_i"] -= 1;
				uv["user_skill_bartering"] = 1
			case 18:
				uv["user_item_book_of_trade_ii"] -= 1;
				uv["user_skill_bargaining"] = 1
			case 19:
				uv["user_item_book_of_trade_iii"] -= 1;
				uv["user_skill_rumours"] = 1
			case 22:
				uv["user_mind_state"] = max(0, uv["user_mind_state"] - random.randint(10, 20))
				uv["user_body"] = max(0, uv["user_body"] - 10)
				uv["user_def"] = uv.get("user_def", user_def) + 2
				uv["user_item_ale"] -= 1
			case 23:
				uv["user_mind_state"] -= 70;
				uv["user_item_wine"] -= 1
			case 24:
				uv["user_mind_state"] = max(0, uv["user_mind_state"] - random.randint(10, 20))
				uv["user_body"] = max(0, uv["user_body"] - 10)
				uv["user_def"] = uv.get("user_def", user_def) + 2
				uv["user_item_rum"] -= 1
			case 27:
				uv["user_status_infection"] = 0;
				uv["user_item_green_herb"] -= 1
			case 28:
				uv["user_status_infected"] = 0;
				uv["user_item_blue_herb"] -= 1
			case 31:
				uv["user_status_infection"] = 0;
				uv["user_item_antibiotics"] -= 1
			case 32:
				uv["user_status_infection"] = 0;
				uv["user_item_betadine"] -= 1
			case 33:
				_vial_heal = int(40 * 0.70) if uv.get("user_class", user_class) == "priest" else 40
				uv["user_body"] += _vial_heal
				uv["user_item_red_vial"] -= 1
				uv["user_item_empty_vial"] += 1
			case 30:
				uv["user_item_ancient_paper"] -= 5
				uv["user_item_book_of_enlightenment"] += 1
