	def _apply_craft_from_recipe(material_name, craft_index_val, uv):
		"""
		Attempt to craft the selected recipe for material_name.
		Strictly validates that the player owns the required quantity.
		Called from render_inventory on ENTER keypress while hovering a material.
		Returns True on success, False if requirements not met.
		"""
		recipes = CRAFT_RECIPES.get(material_name, [])
		if not recipes:
			return False
		idx = craft_index_val % len(recipes)
		result_name, qty_needed = recipes[idx]
		material_ukey = _MATERIAL_NAME_TO_UKEY.get(material_name)
		if material_ukey is None:
			return False
		# Strict count validation
		if uv.get(material_ukey, 0) < qty_needed:
			return False
		# Deduct materials
		uv[material_ukey] -= qty_needed
		# Award result
		if result_name == "Random Skill Book":
			chosen = random.choice(_RANDOM_SKILL_BOOK_POOL)
			uv[chosen] = uv.get(chosen, 0) + 1
		else:
			result_ukey = _ITEM_NAME_TO_UKEY.get(result_name)
			if result_ukey is None:
				return False
			uv[result_ukey] = uv.get(result_ukey, 0) + 1
		return True

	def _inv_nav_sidebar(mouse_x, mouse_y, events, bag_state, pre_state):
		if colide_inventory_stats.collidepoint(mouse_x, mouse_y):
			screen.blit(_scaled_images["elucidate_select_inv"], (5, 22))
			static_text_raw("STATS", color=(0, 0, 0), position=(15, 20), size=35)
			if _clicked(events):
				return "inventory1"
		elif colide_inventory_bag.collidepoint(mouse_x, mouse_y):
			screen.blit(_scaled_images["elucidate_select_inv"], (5, 58))
			static_text_raw("BAG", color=(0, 0, 0), position=(15, 55), size=35)
			if _clicked(events):
				return bag_state
		elif colide_inventory_continue.collidepoint(mouse_x, mouse_y):
			screen.blit(_scaled_images["elucidate_select_inv"], (5, 130))
			static_text_raw("CONTINUE", color=(0, 0, 0), position=(15, 125), size=35)
			if _clicked(events):
				return pre_state if pre_state and pre_state not in ("inventory", "inventory1", "inventory_bag", "inventory_bag2") else map_return_state
		elif colide_inventory_saves.collidepoint(mouse_x, mouse_y):
			screen.blit(_scaled_images["elucidate_select_inv"], (5, 162))
			static_text_raw("WIKI", color=(0, 0, 0), position=(15, 160), size=35)
			if _clicked(events):
				wiki(screen, py_clock)
		elif colide_inventory_exit.collidepoint(mouse_x, mouse_y):
			screen.blit(_scaled_images["elucidate_select_inv"], (5, 194))
			static_text_raw("EXIT", color=(0, 0, 0), position=(15, 195), size=35)
			if _clicked(events):
				return "exit_to_home_via_death"
		return None

