				# ── BATTLE STATUS BARS ────────────────────────────────────────────
				# Drawn every combat frame using only pygame primitives.
				# Bars are local to this block and exist only while fight_general
				# is active — they are never created outside combat.
				def _draw_bar(surf, x, y, w, h, current, maximum, fill_col, bg_col=(30, 30, 30), border_col=(90, 85, 80)):
					"""Draw a filled bar with border. Safe against zero/negative max."""
					_max_safe = max(1, maximum)
					_ratio = max(0.0, min(1.0, current / _max_safe))
					# Background
					pygame.draw.rect(surf, bg_col, (x, y, w, h))
					# Fill
					_fill_w = int(w * _ratio)
					if _fill_w > 0:
						pygame.draw.rect(surf, fill_col, (x, y, _fill_w, h))
					# Highlight strip (top pixel, slightly brighter)
					_hlt = tuple(min(255, c + 40) for c in fill_col)
					pygame.draw.line(surf, _hlt, (x, y), (x + max(0, _fill_w - 1), y))
					# Border
					pygame.draw.rect(surf, border_col, (x, y, w, h), 1)

				_bar_font = fonts.get(13, pygame.font.SysFont("Times New Roman", 13))
				_BAR_W    = 160   # width of every bar
				_BAR_H    = 12    # height of every bar
				_BAR_X    = px    # left-aligned with the stat column

				# ── PLAYER HEALTH BAR ─────────────────────────────────────────────
				_p_body_cur = max(0, int(user_body))
				# Track session max so bar reflects actual current ceiling
